/**
 * Static algorithm database — every set scraped from speedcubedb.com.
 *
 * Use {@link loadAlg} to fetch a (puzzle, set) pair on demand, so unopened sets
 * never ship to the browser.
 *
 * Data is generated by `scramble-stats-build/bin/scrape_speedcubedb.ts`.
 */

import { invert as invertSkewb } from './skewb_notation';
import type { AlgPuzzle } from './alg_catalog';
import { canonicalize3x3WideMoves, duplicateAlgKey } from './alg_notation';
import { canonicalizeInitialU2 } from './alg-html';

export * from './alg_types';
import type { AlgFile, AlgEntry } from './alg_types';

/** CubingApp OH CMLL names mapped onto the canonical CMLL case names. */
const OH_CMLL_TARGETS: Readonly<Record<string, string>> = {
  'Pi Backslash': 'Pi Down Slash',
  'Pi Forward Slash': 'Pi Up Slash',
  'U Forward Slash': 'U Up Slash',
  'U Backslash': 'U Down Slash',
  'U Front Row': 'U Bottom Row',
  'U Back Row': 'U Upper Row',
  'T Front Row': 'T Bottom Row',
  'T Back Row': 'T Top Row',
  'Sune Forward Slash': 'Sune Up Slash',
  'Sune Backslash': 'Sune Down Slash',
  'Antisune Right Bar': 'Anti Sune Right Bar',
  'Antisune Columns': 'Anti Sune Columns',
  'Antisune Backslash': 'Anti Sune Down Slash',
  'Antisune X': 'Anti Sune X',
  'Antisune Forward Slash': 'Anti Sune Up Slash',
  'Antisune Left Bar': 'Anti Sune Left Bar',
};

const algKey = (entry: AlgEntry) => duplicateAlgKey(entry.alg);
const mergedOhCmllEntries = new WeakSet<AlgEntry>();
/** Runtime provenance; an imported OH alternative is still stored in its own set. */
export function isMergedOhCmllEntry(entry: AlgEntry): boolean {
  return mergedOhCmllEntries.has(entry);
}

/** Merge source-only OH CMLL formulas into their canonical CMLL cases. */
export function mergeOhCmll(base: AlgFile, oneHanded: AlgFile): AlgFile {
  if (base.puzzle !== '3x3' || base.set !== 'cmll') return base;
  if (oneHanded.puzzle !== '3x3' || oneHanded.set !== 'oh-cmll') return base;

  const cases = base.cases.map(item => ({ ...item, algs: item.algs.map(entries => [...entries]) }));
  const byName = new Map(cases.map(item => [item.name, item]));

  for (const sourceCase of oneHanded.cases) {
    const canonicalName = OH_CMLL_TARGETS[sourceCase.name] ?? sourceCase.name;
    const target = byName.get(canonicalName);
    if (!target) throw new Error(`OH CMLL source case has no canonical target: ${sourceCase.name}`);
    const targetAlgs = target.algs[0] ?? (target.algs[0] = []);
    const targetIndexByAlg = new Map(targetAlgs.map((entry, index) => [algKey(entry), index]));
    for (const entry of sourceCase.algs.flat()) {
      const key = algKey(entry);
      const existingIndex = targetIndexByAlg.get(key);
      if (existingIndex !== undefined) {
        const existing = targetAlgs[existingIndex];
        targetAlgs[existingIndex] = {
          ...existing,
          tags: [...new Set([...(existing.tags ?? []), 'oh' as const])],
        };
        continue;
      }
      targetIndexByAlg.set(key, targetAlgs.length);
      const imported: AlgEntry = {
        ...entry,
        setup: entry.setup ?? sourceCase.setup,
        tags: [...new Set([...(entry.tags ?? []), 'oh' as const])],
      };
      mergedOhCmllEntries.add(imported);
      targetAlgs.push(imported);
    }
  }

  return { ...base, cases };
}

/**
 * 三阶公式的展示边界兜底。数据库与 API 写入会做同一规范化，这里再处理一次，
 * 避免旧缓存或外部导入数据把 `Rw` / `Fw` 带回任一公式库界面。
 */
export function canonicalize3x3AlgFile(file: AlgFile): AlgFile {
  if (file.puzzle !== '3x3') return file;
  for (const c of file.cases) {
    c.setup = canonicalize3x3WideMoves(c.setup);
    if (c.standard !== undefined) c.standard = canonicalize3x3WideMoves(c.standard);
    for (const entry of c.algs.flat()) {
      entry.alg = canonicalize3x3WideMoves(entry.alg);
      if (entry.setup !== undefined) entry.setup = canonicalize3x3WideMoves(entry.setup);
      if (entry.algHtml !== undefined) entry.algHtml = canonicalize3x3WideMoves(entry.algHtml);
      Object.assign(entry, canonicalizeInitialU2(entry));
    }
    if (c.meta) {
      if (c.meta.scramble !== undefined) c.meta.scramble = canonicalize3x3WideMoves(c.meta.scramble);
      if (c.meta.optimal) {
        for (const solution of Object.values(c.meta.optimal)) {
          if (solution?.scramble !== undefined) {
            solution.scramble = canonicalize3x3WideMoves(solution.scramble);
          }
        }
      }
      if (c.meta.coep?.alg !== undefined) c.meta.coep.alg = canonicalize3x3WideMoves(c.meta.coep.alg);
      if (c.meta.coep?.scramble !== undefined) {
        c.meta.coep.scramble = canonicalize3x3WideMoves(c.meta.coep.scramble);
      }
    }
  }
  return file;
}

export * from './alg_catalog';
export { MIRROR_SETS, MIRROR_ALG_SYNC_SETS } from './alg_mirror';

/**
 * Load an alg set from the server.
 *
 * Source of truth lives in the `alg_sets` / `alg_cases` PG tables; the 41 JSON
 * retired local JSON files are gone. Browser caches per
 * ETag, checking freshness on each load instead of keeping edits hidden for an hour.
 */
// `declare const process` keeps the literal `process.env.NODE_ENV` token sequence intact
// so Webpack/Turbopack can replace it with a string literal at build time. Wrapped in a
// function so the fallback also stays safe in browser bundles without `process`.
declare const process: { env: { NODE_ENV?: string } };
function nodeProcessEnv(): string | undefined {
  return process.env.NODE_ENV;
}

/** Hosts without HTTP (watchOS) supply the same versioned AlgFile data offline. */
export type AlgFileLoader = (puzzle: AlgPuzzle, set: string, opts?: { fresh?: boolean }) => Promise<AlgFile>;
let algFileLoader: AlgFileLoader | null = null;
export function configureAlgFileLoader(loader: AlgFileLoader | null): void { algFileLoader = loader; }

async function fetchAlgFile(puzzle: AlgPuzzle, set: string, opts?: { fresh?: boolean }): Promise<AlgFile> {
  // NOTE: 用 build-time NODE_ENV 而不是 hostname 检查 — 走 LAN IP / 隧道域名(dev.cuberoot.me)
  // 等其它 dev host 时,hostname 检查会错判成 prod 直接打 api.cuberoot.me 跨域,
  // 而 api 的 CORS allowlist 没那些 host → 浏览器拦截。server 端 loadAlg 不被调,
  // NODE_ENV 非 development 走 prod 分支也无害。
  // Webpack/Turbopack replace `process.env.NODE_ENV` as a string literal at build time,
  // but only when accessed by that literal token sequence, and `process` isn't defined
  // in browser bundles — wrap in try so it doesn't ReferenceError.
  // `declare const process` keeps the literal token sequence so the bundler replaces it.
  let nodeEnv: string | undefined;
  try { nodeEnv = nodeProcessEnv(); } catch { /* not in Node/bundler context */ }
  const isDev = nodeEnv === 'development';
  const base = isDev
    ? '/v1/alg/sets'  // dev: Next rewrite proxy
    : 'https://api.cuberoot.me/v1/alg/sets';  // prod: 跨域到 API 子域
  // 每次读取都核对版本；fresh 保留管理员显式强制读取的兼容入口。
  const query = new URLSearchParams();
  // The SQ1 CS data was realigned to Squanmate's canonical 170-case table.
  // Keep this versioned query until every pre-migration one-hour cache has expired,
  // otherwise a new client can briefly pair migrated user keys with stale case data.
  if (puzzle === 'sq1' && set === 'cs') query.set('v', '2026-08-15-squanmate');
  // Five EP source formulas omitted their final U/D alignment. Bust the public
  // cache so their corrected setups and thumbnails replace the malformed state immediately.
  if (puzzle === 'sq1' && set === 'ep') query.set('v', '2026-08-31-ep-auf');
  // PF/TL setups changed from a fully-solved target to their real intermediate stages.
  // Bust the public one-hour cache so deployed clients do not keep the old states.
  if (puzzle === 'fto' && (set === 'pf' || set === 'tl')) query.set('v', '2026-08-19-fto-stages');
  if (opts?.fresh) query.set('_', String(Date.now()));
  const queryString = query.toString();
  const url = `${base}/${encodeURIComponent(puzzle)}/${encodeURIComponent(set)}`
    + (queryString ? `?${queryString}` : '');
  const res = await fetch(url, { cache: 'no-cache' });
  if (!res.ok) throw new Error(`Failed to load alg ${puzzle}/${set}: HTTP ${res.status}`);
  return await res.json() as AlgFile;
}

export async function loadAlg(puzzle: AlgPuzzle, set: string, opts?: { fresh?: boolean; loader?: AlgFileLoader }): Promise<AlgFile> {
  const oneHandedCmll = puzzle === '3x3' && set === 'cmll'
    ? loadAlg('3x3', 'oh-cmll', opts).catch(() => null)
    : null;
  let file = canonicalize3x3AlgFile(await (opts?.loader ?? algFileLoader ?? fetchAlgFile)(puzzle, set, opts));
  if (oneHandedCmll) {
    const source = await oneHandedCmll;
    if (source) file = mergeOhCmll(file, source);
  }
  // Skewb algs are full solves with no AUF, so a case's scramble is exactly the
  // inverse of its (first) alg. The scraped `setup` strings are buggy WCA-ified
  // inverses (some even contain cancellations like `R' R`), which then feed the
  // scramble text, the thumbnail state and the 3D player — all wrong. Regenerate
  // them from the alg here, once, so every consumer (library + trainer) is correct.
  if (file.puzzle === 'skewb') {
    for (const c of file.cases) {
      const first = c.algs.flat()[0]?.alg ?? c.standard ?? '';
      if (first) c.setup = invertSkewb(first);
    }
  }
  return file;
}
